use super::*;

fn m(s: &[&str]) -> Markers {
    measure(&s.iter().map(|x| (*x).to_string()).collect::<Vec<_>>())
}

/// The maintainer's own habits, as measured 2026-09-08. Not a synthetic fixture — these are the
/// shapes the corpus actually produced, so a change that stops detecting them is a real regression.
fn maintainer() -> Markers {
    m(&[
        "lets get this built. i think we should check the thresold first",
        "alot of these dont matter, nevermind that",
        "ok cool >:D i'll look at it",
        "can we do the same for the other one? ect",
        "im not sure thats right, whats the plan",
    ])
}

fn formal() -> Markers {
    m(&[
        "Let us proceed with the build. I think we should check the threshold first.",
        "A lot of these do not matter; never mind that.",
        // At least one APOSTROPHISED contraction, deliberately: a writer who never contracts at all
        // gives this dimension nothing to measure, and it correctly reports ABSENT rather than 0.0 —
        // pinned separately below. The fixture has to contract for the comparison to exist at all.
        "Understood. I'll look at it.",
        "Can we do the same for the other one, etc.",
        "I am not sure that is right. What is the plan?",
    ])
}

#[test]
fn the_three_strong_dimensions_separate_the_two_writers() {
    let (a, b) = (maintainer(), formal());
    for name in [CAP_START, LOWERCASE_I, APOS_OMIT] {
        let (x, y) = (a.get(name).unwrap(), b.get(name).unwrap());
        assert!(x.measured() && y.measured(), "{name} must be measurable in both samples");
        assert!(
            (x.value - y.value).abs() > 0.5,
            "{name} should separate these writers: {} vs {}",
            x.value,
            y.value
        );
    }
    // And the direction is the measured one: the maintainer writes lowercase, without apostrophes.
    assert!(a.get(CAP_START).unwrap().value < 0.2);
    assert!(a.get(LOWERCASE_I).unwrap().value > 0.8);
    assert!(b.get(CAP_START).unwrap().value > 0.8);
    assert!(b.get(LOWERCASE_I).unwrap().value < 0.2);
}

#[test]
fn a_habitual_misspelling_is_a_ratio_against_its_correct_form() {
    // The signal is not "wrote thresold" — it is "wrote thresold AND never threshold". Someone who
    // does both is a different claim from someone who only ever gets it wrong.
    let always_wrong = m(&["the thresold is alot lower", "nevermind, ect"]);
    let always_right = m(&["the threshold is a lot lower", "never mind, etc"]);
    let mixed = m(&["the thresold is wrong", "the threshold is right"]);
    assert_eq!(always_wrong.get(HABIT_MISSPELL).unwrap().value, 1.0);
    assert_eq!(always_right.get(HABIT_MISSPELL).unwrap().value, 0.0);
    let mid = mixed.get(HABIT_MISSPELL).unwrap().value;
    assert!((mid - 0.5).abs() < 1e-9, "a 50/50 writer reads as 0.5, not as either extreme: {mid}");
}

#[test]
fn a_dimension_with_nothing_to_measure_is_absent_not_zero() {
    // The house rule, and the one that decides whether a short message is readable at all: text with
    // no first-person pronoun has an UNKNOWN lowercase-i habit, not a habit of 0.0.
    let no_pronoun = m(&["build the thing"]);
    let d = no_pronoun.get(LOWERCASE_I).unwrap();
    assert_eq!(d.n, 0, "nothing was observed");
    assert!(!d.measured(), "so it must not present as measured");
    // …and `discriminative()` refuses to hand an unmeasured dimension to a comparison at all.
    assert!(!no_pronoun.discriminative().any(|x| x.name == LOWERCASE_I));
}

#[test]
fn a_message_opening_with_a_path_or_flag_does_not_count_as_lowercase() {
    // Counting it would make anyone who pastes look like they never capitalise — the dimension would
    // measure paste habits rather than writing habits.
    let pasted = m(&["/home/x/y is broken", "--force did nothing", "Then I fixed it"]);
    let d = pasted.get(CAP_START).unwrap();
    assert_eq!(d.n, 3, "the first ALPHABETIC character is read, so all three messages count");
    assert!((d.value - 1.0 / 3.0).abs() < 1e-9, "one of three is capitalised: {}", d.value);
}

#[test]
fn a_longer_emoticon_is_not_eaten_by_a_shorter_one_inside_it() {
    let x = m(&["nice >:D and also :D"]);
    let faces: std::collections::BTreeMap<_, _> = x.emoticons.iter().cloned().collect();
    assert_eq!(faces.get(">:d"), Some(&1), "the long face is counted whole");
    assert_eq!(faces.get(":d"), Some(&1), "and the bare one separately, not twice");
}

#[test]
fn explain_reads_only_the_discriminative_dimensions() {
    // The measured finding this whole design turns on: averaging the weak dimensions into the strong
    // ones made cross-author overlap WORSE (537 -> 1327 of 1764). So a comparison must not see them.
    let profile = Profile {
        id: "me".into(),
        markers: maintainer(),
        behaviour: Default::default(),
        sources: vec![],
        updated_at_ms: 0,
    };
    let e = explain(&profile, &formal());
    let compared: Vec<&str> = e.readings.iter().map(|r| r.name.as_str()).collect();
    for weak in [EMOTICON_RATE, MEAN_WORD_LEN, MEAN_MSG_WORDS] {
        assert!(!compared.contains(&weak), "{weak} is descriptive and must never be compared");
    }
    assert!(compared.contains(&CAP_START) && compared.contains(&LOWERCASE_I));
    // They are still REPORTED — dropped from the comparison, not from the report.
    let shown: Vec<&str> = e.descriptive.iter().map(|r| r.name.as_str()).collect();
    assert!(shown.contains(&MEAN_WORD_LEN));
}

#[test]
fn explain_emits_no_verdict_and_no_overall_score() {
    // Asserted against the SERIALIZED form, because that is what a caller sees and what a future
    // field would appear in. A score here is what turns an instrument into a suspicion ledger.
    let profile = Profile { id: "me".into(), markers: maintainer(), behaviour: Default::default(), sources: vec![], updated_at_ms: 0 };
    let json = serde_json::to_string(&explain(&profile, &formal())).unwrap();
    for forbidden in ["score", "verdict", "confidence", "match\"", "isUser", "is_user", "likely"] {
        assert!(!json.contains(forbidden), "explain must not emit `{forbidden}`: {json}");
    }
}

#[test]
fn accumulate_weights_by_evidence_and_keeps_absent_absent() {
    let big = m(&["i think i can. i will. i do."; 20]);
    let tiny = m(&["I do"]);
    let folded = accumulate(&big, &tiny);
    let b = big.get(LOWERCASE_I).unwrap().value;
    let f = folded.get(LOWERCASE_I).unwrap().value;
    assert!(f < b, "one uppercase I moves the habit…");
    assert!(b - f < 0.05, "…but only slightly, because it is one observation against many: {b} -> {f}");
    assert_eq!(folded.words, big.words + tiny.words, "the corpus grows");

    // Absent + absent stays absent, rather than becoming a confident 0.0.
    let none = m(&["build it"]);
    let still = accumulate(&none, &m(&["ship it"]));
    assert!(!still.get(LOWERCASE_I).unwrap().measured());
}

#[test]
fn accumulate_unions_the_emoticon_vocabulary() {
    // Which faces someone uses is more identifying than how often, so the vocabulary accumulates
    // even though the RATE is only descriptive.
    let a = m(&["yes <3"]);
    let b = m(&["sure >:D and <3"]);
    let f = accumulate(&a, &b);
    let faces: std::collections::BTreeMap<_, _> = f.emoticons.iter().cloned().collect();
    assert_eq!(faces.get("<3"), Some(&2));
    assert_eq!(faces.get(">:d"), Some(&1), "a face seen only in the new corpus is adopted");
}

#[test]
fn an_under_evidenced_profile_says_so() {
    let thin = Profile { id: "me".into(), markers: m(&["hello"]), behaviour: Default::default(), sources: vec![], updated_at_ms: 0 };
    assert!(!thin.evidenced(), "one word is not a profile");
    let e = explain(&thin, &maintainer());
    assert!(!e.profile_evidenced, "and the report says so rather than reading confidently");
}

#[test]
fn an_unseen_emoticon_is_reported_as_unseen_and_nothing_more() {
    // `>:D` was absent from the maintainer's first 60k words and then appeared. That is a person
    // using a new face, which people do — so it is surfaced as new, never as evidence.
    let profile = Profile { id: "me".into(), markers: m(&["ok <3"]), behaviour: Default::default(), sources: vec![], updated_at_ms: 0 };
    let e = explain(&profile, &m(&["ok >:D"]));
    assert_eq!(e.unseen_emoticons, vec![">:d".to_string()]);
}

#[test]
fn a_writer_who_never_contracts_yields_no_apostrophe_evidence_at_all() {
    // Not a rate of 0.0 — no observation. This is the difference between "always uses apostrophes"
    // and "we have never seen them face the choice", and reading the second as the first is exactly
    // the failure the codebase names in fourteen other places.
    let never = m(&["I do not think that is right. It is not.", "We will not proceed."]);
    let d = never.get(APOS_OMIT).unwrap();
    assert_eq!(d.n, 0);
    assert!(!d.measured());
    assert!(!never.discriminative().any(|x| x.name == APOS_OMIT), "so no comparison may use it");
}

#[test]
fn a_generated_session_charter_is_not_typing() {
    // THE CONTAMINATION GUARD. `history.jsonl` records every prompt the app SENDS, and 895 of one
    // corpus's 3,215 entries were byte-identical copies of one injected charter. Built on the raw
    // file, the profile learns to recognise the APP — and it does so INVISIBLY, by pulling every
    // dimension toward formal prose rather than by failing.
    // The fixtures have to be LONG, because that is what the real ones are (~470 words) and because
    // the length floor is doing the work. A truncated charter is indistinguishable from a person
    // saying "you are right" — see the second half of this test.
    let filler = " and then it explains the workflow at length".repeat(12);
    for opening in [
        "You are the base-studio-code DEBUG session. You have full read/write access to this repository.",
        "Your job is the whole application's surface: every session that hits a wall files onto one queue.",
        "Read the brief at /tmp/x and follow it exactly.",
    ] {
        let generated = format!("{opening}{filler}");
        assert!(crate::cli::looks_generated(&generated), "must be recognised as generated: {opening}");
    }
    // …and a person's own writing is not. THE TRADE IS DELIBERATE AND ASYMMETRIC: a SHORT
    // second-person brief is not caught, because catching it would also throw away "you are right",
    // which the maintainer writes. Losing real typing shrinks the corpus silently and skews every
    // dimension; keeping the odd short brief costs a few words out of fifty thousand.
    for typed in [
        "lets get this built. i dont think the thresold matters alot here",
        "you are right, that was my mistake — nevermind",
        "can we check the other one? ect",
    ] {
        assert!(!crate::cli::looks_generated(typed), "must be treated as typing: {typed}");
    }
}

#[test]
fn a_very_long_prompt_is_treated_as_pasted_not_typed() {
    // The median typed prompt is 15 words. A 400-word one is a spec someone pasted, and measuring it
    // profiles the clipboard rather than the person.
    let long = "word ".repeat(400);
    assert!(crate::cli::looks_generated(&long));
    let normal = "word ".repeat(50);
    assert!(!crate::cli::looks_generated(&normal));
}

// ── the behavioural channel ──────────────────────────────────────────────────

use crate::behaviour::{
    accumulate_behaviour, explain_behaviour, measure_behaviour, Event, HOUR_OF_DAY, PROJECT, WEEKDAY,
};

fn ev(at_ms: i64, project: &str) -> Event {
    Event { text: "x".into(), at_ms, project: project.into() }
}

#[test]
fn the_epoch_was_a_thursday_at_midnight_utc() {
    // The only arithmetic here that can be silently wrong. 1970-01-01 was a THURSDAY, which is the
    // +4 in the weekday derivation; get it wrong and every weekday shifts by a constant, which looks
    // like a plausible distribution rather than a bug.
    let b = measure_behaviour(&[ev(1, ""), ev(86_400_000, ""), ev(3 * 86_400_000, "")]);
    let wd = b.get(WEEKDAY).unwrap();
    assert_eq!(wd.counts.get("Thu"), Some(&1), "the epoch itself");
    assert_eq!(wd.counts.get("Fri"), Some(&1), "one day later");
    assert_eq!(wd.counts.get("Sun"), Some(&1), "three days later");
    let hr = b.get(HOUR_OF_DAY).unwrap();
    assert_eq!(hr.counts.get("00"), Some(&3), "all three are just after midnight UTC");
}

#[test]
fn an_unknown_time_contributes_to_nothing_rather_than_to_hour_zero() {
    // A message whose occasion we do not know says NOTHING about when someone works. Folding it into
    // hour 00 would invent a habit out of missing data — the same defect as reading an unmeasured
    // dimension as 0.0.
    let b = measure_behaviour(&[ev(0, "p"), ev(0, "p")]);
    assert_eq!(b.get(HOUR_OF_DAY).unwrap().n, 0, "no hours observed");
    assert!(b.get(HOUR_OF_DAY).unwrap().counts.is_empty());
    // …but the project is known, so THAT axis still learns.
    assert_eq!(b.get(PROJECT).unwrap().n, 2);
}

#[test]
fn an_empty_project_is_not_a_project() {
    let b = measure_behaviour(&[ev(1, ""), ev(1, "   "), ev(1, "real")]);
    let p = b.get(PROJECT).unwrap();
    assert_eq!(p.n, 1);
    assert_eq!(p.counts.get("real"), Some(&1));
}

#[test]
fn a_never_observed_category_reads_as_zero_mass_with_its_denominator() {
    // The sharpest reading this channel has, and the one that must not be inflated into a verdict.
    let profile = measure_behaviour(&(0..100).map(|i| ev(1 + i, "mine")).collect::<Vec<_>>());
    let r = explain_behaviour(&profile, &ev(1, "theirs"));
    let proj = r.iter().find(|x| x.name == PROJECT).unwrap();
    assert_eq!(proj.category.as_deref(), Some("theirs"));
    assert_eq!(proj.share, Some(0.0));
    assert_eq!(proj.profile_count, 0);
    // The denominator ships with it: never-in-100 and never-in-5 are different facts, and a reader
    // cannot tell them apart from the share alone.
    assert_eq!(proj.profile_n, 100);
}

#[test]
fn a_familiar_category_reads_as_its_share_of_history() {
    let mut events: Vec<Event> = (0..90).map(|i| ev(1 + i, "mine")).collect();
    events.extend((0..10).map(|i| ev(1 + i, "other")));
    let profile = measure_behaviour(&events);
    let r = explain_behaviour(&profile, &ev(1, "mine"));
    let proj = r.iter().find(|x| x.name == PROJECT).unwrap();
    assert!((proj.share.unwrap() - 0.9).abs() < 1e-9, "{:?}", proj.share);
    assert_eq!(proj.profile_count, 90);
}

#[test]
fn accumulate_behaviour_adds_the_histograms() {
    let a = measure_behaviour(&[ev(1, "p"), ev(1, "p")]);
    let b = measure_behaviour(&[ev(1, "p"), ev(1, "q")]);
    let f = accumulate_behaviour(&a, &b);
    let p = f.get(PROJECT).unwrap();
    assert_eq!(p.n, 4);
    assert_eq!(p.counts.get("p"), Some(&3));
    assert_eq!(p.counts.get("q"), Some(&1), "a category seen only in the new corpus is adopted");
}

#[test]
fn explain_without_an_occasion_reports_no_behaviour_at_all() {
    // `bsc imprint explain "<text>"` on a bare string has no occasion, and the behavioural half must
    // be ABSENT rather than defaulting to now-and-nowhere — which would read every such call as a
    // message sent from an unknown project.
    let profile = Profile {
        id: "me".into(),
        markers: maintainer(),
        behaviour: measure_behaviour(&[ev(1, "mine")]),
        sources: vec![],
        updated_at_ms: 0,
    };
    let e = crate::explain(&profile, &formal());
    assert!(e.behaviour.is_empty());
    let with = crate::explain_at(&profile, &formal(), Some(&ev(1, "mine")));
    assert_eq!(with.behaviour.len(), 3, "hour, weekday and project");
}

#[test]
fn the_behavioural_readings_carry_no_verdict_either() {
    let profile = Profile {
        id: "me".into(),
        markers: maintainer(),
        behaviour: measure_behaviour(&[ev(1, "mine")]),
        sources: vec![],
        updated_at_ms: 0,
    };
    let json = serde_json::to_string(&crate::explain_at(&profile, &formal(), Some(&ev(1, "theirs")))).unwrap();
    for forbidden in ["score", "verdict", "confidence", "anomal", "suspicious", "likely"] {
        assert!(!json.contains(forbidden), "must not emit `{forbidden}`: {json}");
    }
}
